  }

  function setError(fieldEl, message) {
    fieldEl.classList.add('is-invalid');
    fieldEl.querySelector('.form-field__error').textContent = message;
  }

  function clearError(fieldEl) {
    fieldEl.classList.remove('is-invalid');
    fieldEl.querySelector('.form-field__error').textContent = '';
  }

  function validateField(input) {
    const fieldEl = input.closest('.form-field');
    const value = input.value.trim();

    if (input.id === 'fullName') {
      if (!value) {
        setError(fieldEl, 'Full name is required.');
        return false;
      }
      if (value.length < 2) {
        setError(fieldEl, 'Please enter your full name.');
        return false;
      }
    }

    if (input.id === 'email') {
      if (!value) {
        setError(fieldEl, 'Email address is required.');
        return false;
      }
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
        setError(fieldEl, 'Please enter a valid email address.');
        return false;
      }
    }

    if (input.id === 'phone' && value) {
      if (!PHONE_RE.test(value)) {
        setError(fieldEl, 'Please enter a valid phone number.');
        return false;
      }
    }

    clearError(fieldEl);
    return true;
  }

  // Validate on blur only after the first submission attempt
  let submitted = false;

  form.addEventListener('blur', function (e) {
    if (!submitted) return;
    if (e.target.matches('.form-field__input')) {
      validateField(e.target);
    }
  }, true);

  form.addEventListener('input', function (e) {
    if (!submitted) return;
    if (e.target.matches('.form-field__input')) {
      validateField(e.target);
    }
  });

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    submitted = true;

    const inputs = form.querySelectorAll('.form-field__input');
    let valid = true;

    inputs.forEach(function (input) {
      if (!validateField(input)) valid = false;
    });

    if (!valid) {
      const firstInvalid = form.querySelector('.form-field.is-invalid .form-field__input');
      if (firstInvalid) firstInvalid.focus();
      return;
    }

    form.hidden = true;
    successMessage.hidden = false;
  });

  resetBtn.addEventListener('click', function () {
    form.reset();
    submitted = false;
    form.querySelectorAll('.form-field__input').forEach(function (input) {
      clearError(input.closest('.form-field'));
    });
    successMessage.hidden = true;
    form.hidden = false;
    form.querySelector('.form-field__input').focus();
  });
})();
